{
  "spells": [
    {
      "id": "spell_water_10",
      "theory": "施术者将魔力注入水流，使水分子间的牵引力暂时增强，从而减缓流速。这只能削弱小股急流，对洪峰无效。施术需要持续维持魔力输入。",
      "casting": "双手浸入水中，掌心相对，缓缓输出魔力，同时低声念诵简短水纹符文。维持手势直到水流变缓。",
      "failure": "若魔力输出不稳，水流会突然反弹，溅起水花打湿施术者。严重时，局部水流紊乱，可能冲走附近的小物件。",
      "counters": [
        "向水中投入散魔石，可吸收维持法术的魔力。",
        "用强风吹散水面的魔力纹路，使法术中断。"
      ],
      "socialConsequences": "在河谷，乡约见证下，施术者常被请去保护磨坊或渡口，但若因此改变河道影响下游，可能被追究责任。城市中，公会要求施术前报备，避免影响航运。港口则关注是否妨碍船只通行。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时，水流减缓幅度小，持续时间短。",
        "熟练后，能稳定减缓指定区域的水流。",
        "精准控制范围，减少对周围水流的影响。",
        "可同时减缓两处小急流，但总效果不变。"
      ]
    },
    {
      "id": "spell_water_11",
      "theory": "魔力在封闭空间内循环，吸收热量并维持低温。木柜隔热差时，魔力消耗加快。法术作用于储柜内部，使其保持阴凉。",
      "casting": "将手贴在柜壁，画出闭合的冰纹符文，注入魔力，直到柜内温度下降。",
      "failure": "符文不完整会导致降温不均，部分食物仍会腐坏。魔力反冲可能使柜壁结霜，但内部温度并未降低。",
      "counters": [
        "打开柜门让外界热空气涌入，可抵消降温效果。",
        "用火焰靠近柜壁，加速魔力消耗，使法术提前结束。"
      ],
      "socialConsequences": "在河谷，农户用此术保存蔬果，但乡约要求不得因此垄断市场。城市中，公会许可后才可商用，否则视为扰乱物价。港口用于保存渔获，但港务规定若因降温不当导致货损，需赔偿。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常需多次尝试才能达到理想温度。",
        "熟练后，能根据柜子材质调整魔力输出。",
        "可精确控制温度，减少魔力浪费。",
        "维持时间更长，但仍受材质限制。"
      ]
    },
    {
      "id": "spell_water_12",
      "theory": "魔力引导地下水汽向土壤表层汇聚，增加湿度。需要附近有水源，且土壤能吸收水分。法术只补湿，不直接创造水。",
      "casting": "单膝跪地，手掌按在田垄上，绘制水纹符文，缓慢注入魔力，同时感知土壤湿度。",
      "failure": "若土壤过于干燥，魔力会迅速散失，仅表面湿润。若水源不足，可能导致附近水洼干涸，影响其他作物。",
      "counters": [
        "在田垄上撒石灰，破坏魔力传导路径。",
        "用犁翻动土壤，打断水汽汇聚。"
      ],
      "socialConsequences": "河谷中，乡约见证下，施术者需确保不影响邻田用水。城市中，公会要求登记，避免过度取水。港口附近农田使用此术时，港务会关注是否影响码头用水。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时，补湿范围小，深度浅。",
        "熟练后，能均匀湿润整条田垄。",
        "可控制湿度，避免积水。",
        "在缺水环境下，效率提高，但总水量不变。"
      ]
    }
  ]
}
